%[text] # 处理XL-80导出的数据
close all;
clear; clc;
cd(fileparts(which ("start_up.m")));

set(groot, 'DefaultAxesFontName', 'Times New Roman', 'DefaultAxesFontSize', 12);
set(groot, 'DefaultTextFontName', 'Times New Roman', 'DefaultTextFontSize', 12);
set(groot, 'DefaultAxesXMinorTick', 'on');

GEOMETRIC_ERROR_MAP = 'data/X_positioning_error.mat';

FILE_PATH = char("D:\Sync\syncthing\Data\202406-mms-dynamics\xl80 results\20240530 xl80\XD-Y0_A3J80.csv");
[~, fileName, ~] = fileparts(FILE_PATH);
theoAccelPattern = 'A(\d+)'; % 匹配"A"后面的数字
match = regexp(fileName, theoAccelPattern, 'tokens');
theoAccel = str2double(match{1}{1});
clear theoAccelPattern match;


fid = fopen(FILE_PATH);
for ii = 1:100
    tline = fgetl(fid);
    if contains(tline,'Time,Measurement')
        break;
    end
end
fclose(fid);

opts = detectImportOptions(FILE_PATH,"FileType","delimitedtext","NumHeaderLines",ii - 1);
dataTable = readtable(FILE_PATH,opts);
xl80Data = struct("Time",dataTable.Time,"Displacement",dataTable.Measurement);
% xl80Data = renamevars(xl80Data,"Measurement","Displacement");
xl80Data.Displacement = -1.*xl80Data.Displacement;

% Parameters for character extraction
DISP_MinPeakProminence = 10; % Measured point A, B, D
VELO_MinPeakProminence = 10;
ACCEL_MinPeakProminence = 0.5;
isFluctuation = false; % false for measured A, B, C, and J5 in D;
%%
%[text] ## --------------------------- 位移数据处理：开始方向确认 ---------------------------
%[text] 不同的数据，测量的开始位置和方向并未统一，需要在此统一为：
%[text] X轴数据以X=-1000为起点沿负方向遍历，Y轴数据以Y=0为起点沿正方形遍历（即与几何误差表一致）  
%[text] **不同测点的情况会有不同，在换测点时必须留意此处！！！！！**
%[text] **X轴A、D测点只需要将起始点平移到X=-1000即可**
%[text] **X轴B测点需取反，再将起始点平移到X=-3000**
%[text] **X轴C测点**
% X轴A、D测点：X=-1000~X=-5500
% xl80Data.Displacement = xl80Data.Displacement - 1000 + xl80Data.Displacement(1);
% X轴B测点：X=-3000~X=-7000
% xl80Data.Displacement = -1 * xl80Data.Displacement - 3000 + xl80Data.Displacement(1);
% X轴C测点：X=-4200~X=-4300
% xl80Data.Displacement = -1 * xl80Data.Displacement - 4200 + xl80Data.Displacement(1);
% X轴C测点：X=-6900~X=-7000
% xl80Data.Displacement = -1 * xl80Data.Displacement - 6900 + xl80Data.Displacement(1);

fig1 = figure('Name', '【XL-80】位移原始图像'); %[output:6c42466f]
ax1 = axes(fig1); %[output:6c42466f]
plot(ax1, xl80Data.Time, xl80Data.Displacement); %[output:6c42466f]
hold(ax1, "on"); %[output:6c42466f]
xlabel(ax1, 'Time (s)'); %[output:6c42466f]
ylabel(ax1, 'Displacement (mm)'); %[output:6c42466f]
drawnow;

clear fig1 ax1;
%%
%[text] ## --------------------------------- 位移数据处理 ----------------------------------
% if isempty(gcp('nocreate'))
%     parpool;
% end
% tmpDispSmooth = zeros(size(tmpDisp));
% block_size = 10000;
% num_blocks = ceil(length(tmpDisp) / block_size);
% % 并行分块处理数据
% tic
% for i = 1:num_blocks
%     temp_smooth = zeros(1, block_size);
% 
%     start_idx = (i-1) * block_size + 1;
%     end_idx = min(i * block_size, length(tmpDisp));
% 
%     temp_smooth(1:(end_idx-start_idx+1)) = smoothdata(tmpDisp(start_idx:end_idx), ...
%         'sgolay', 51, 'SamplePoints', tmpTime(start_idx:end_idx), 'Degree', 2);
%     tmpDispSmooth(start_idx:end_idx) = temp_smooth(1:(end_idx-start_idx+1));
% end
% toc
% tmpDispSmooth = smoothdata(tmpDisp, 'sgolay', 7, 'SamplePoints', tmpTime, 'Degree', 3);
% hold on;
% plot(tmpTime, tmpDispSmooth);


% ------------ 滤波与抽样 ------------
% Data low-pass filtering for denoising
WAVE_NAME = 'sym9'; % 小波基
NUM_LEVEL = min(21, wmaxlev(length(xl80Data.Displacement),WAVE_NAME)); % 分解层数，越高越平滑
dispWavelet = wdenoise(xl80Data.Displacement,NUM_LEVEL, ...
    Wavelet=WAVE_NAME, ...
    DenoisingMethod='Bayes', ...
    ThresholdRule='Soft', ...
    NoiseEstimate='LevelIndependent');

% dispWavelet = xl80Data.Displacement;

% Data downsampling
DOWN_SAMPLE_RATE = 10;
downsampleTime = xl80Data.Time(1:DOWN_SAMPLE_RATE:end);
downsampleDisp = dispWavelet(1:DOWN_SAMPLE_RATE:end);

% 计算滤波抽样后的时间间隔和采样率
timeTerminal = downsampleTime(2) - downsampleTime(1);
sampleRate = 1 / timeTerminal;

% ------------ 定位误差滤除 ------------
% load the geometric error fitting result
load(GEOMETRIC_ERROR_MAP);

% take the geometric error into account
geometricError = ppval(geometric_error_pp, downsampleDisp);
geometricRemoveDisp = downsampleDisp - geometricError;

% plot the geometric error
fig2 = figure('Name', '【IDS】位移定位误差滤除'); %[output:4f2de327]
ax2 = axes(fig2); %[output:4f2de327]
yyaxis(ax2, "left"); %[output:4f2de327]
plot(ax2, downsampleTime, downsampleDisp); %[output:4f2de327]
ylabel(ax2, "Original Displacement (mm)"); %[output:4f2de327]
y_min = min(downsampleDisp);
y_max = max(downsampleDisp);
if y_min > 0
    ylim([0, y_max]);
elseif y_max < 0
    ylim([y_min, 0]);
else
    ylim([y_min, y_max]); %[output:4f2de327]
end
yyaxis(ax2, "right"); %[output:4f2de327]
area(ax2, downsampleTime, geometricError, 0, ... %[output:4f2de327]
    "EdgeColor", [0.8500 0.3250 0.0980], "EdgeAlpha", 0.5, ... %[output:4f2de327]
    "FaceColor", [0.8500 0.3250 0.0980], "FaceAlpha", 0.1); %[output:4f2de327]
ylabel(ax2, "Geometric Error (mm)"); %[output:4f2de327]
xlabel(ax2, "Time (s)"); %[output:4f2de327]

% ------------ 计算滤波后的速度 ------------
xl80Data.veloTime = 0.5 * (downsampleTime(1:end - 1) + downsampleTime(2:end));
xl80Data.velo = 60 * diff(downsampleDisp) ./ diff(downsampleTime);

% 画位置和速度的滤波图像
figure('name', '【IDS】位移滤波效果'); %[output:5a1fb929]
tiledlayout(2, 1); %[output:5a1fb929]
ax1 = nexttile; %[output:5a1fb929]
plot(xl80Data.Time, xl80Data.Displacement, 'DisplayName', 'Raw'); %[output:5a1fb929]
hold on; %[output:5a1fb929]
plot(xl80Data.Time, dispWavelet, 'DisplayName', 'Filtered'); %[output:5a1fb929]
legend; %[output:5a1fb929]
ylabel('Displacement (mm)'); %[output:5a1fb929]
ax2 = nexttile; %[output:5a1fb929]
plot(0.5 * (xl80Data.Time(1:end - 1) + xl80Data.Time(2:end)), ... %[output:5a1fb929]
    60 * diff(xl80Data.Displacement) ./ diff(xl80Data.Time), ... %[output:5a1fb929]
    'LineWidth', 1, 'DisplayName', 'Original'); %[output:5a1fb929]
hold on; %[output:5a1fb929]
plot(xl80Data.veloTime, xl80Data.velo, 'LineWidth', 1, 'DisplayName', 'Filtered'); %[output:5a1fb929]
legend; %[output:5a1fb929]
% ylim([min(xl80Data.velo), max(xl80Data.velo)]);
xlabel('Time (s)'); %[output:5a1fb929]
ylabel('Velocity (mm/min)'); %[output:5a1fb929]
linkaxes([ax1, ax2], 'x'); %[output:5a1fb929]
drawnow;

% 存储位移数据处理结果
xl80Data.Time = downsampleTime;
xl80Data.Displacement = geometricRemoveDisp;

clear downsampleTime downsampleDisp geometricRemoveDisp dispWavelet ax2 fig2;
%%
%[text] ## --------------------------- 速度滤波处理（为了加速度计算） ---------------------------
% 速度曲线滤波
% xl80Data.velo_filtered = xl80Data.velo;
% 高斯滤波，不能解决匀加减速过程，或者匀速过程抖动对加速度计算的影响。
% siemensData.velo1_filtered = filter_gaussian(100, 1, siemensData.velo);
% 三次样条加权平滑
% veloPeaks = peak_segmentation(xl80Data.veloTime, xl80Data.velo, [], ...
%     "IsNormalization", false, ...
%     "MinPeakDistance", 4, "MinPeakProminence", 10000, 'MinPeakWidth', 1);
% weights = ones(size(xl80Data.veloTime));
% weightFactor = 1;
% weights(veloPeaks.ind) = weights(veloPeaks.ind) * weightFactor;
sp = spaps(xl80Data.veloTime, xl80Data.velo, 5000000, [], 2);
xl80Data.velo_filtered = fnval(sp, xl80Data.veloTime);
% clear sp veloPeaks;
% 小波
% WAVE_NAME = 'sym9'; % 小波基
% NUM_LEVEL = min(21, wmaxlev(length(xl80Data.velo),WAVE_NAME)); % 分解层数，越高越平滑
% xl80Data.velo_filtered = wdenoise(xl80Data.velo, NUM_LEVEL, ...
%     Wavelet=WAVE_NAME, ...
%     DenoisingMethod='Bayes', ...
%     ThresholdRule='Soft', ...
%     NoiseEstimate='LevelIndependent');

% 计算加速度
xl80Data.accelTime = 0.5 * (xl80Data.veloTime(1:end - 1) + xl80Data.veloTime(2:end));
xl80Data.accel = diff(xl80Data.velo_filtered) ./ diff(xl80Data.veloTime) ./ 60000;

% 查看速度滤波的效果 （结果就是滤波作用不大）
figure('Name','【IDS】速度滤波结果'); %[output:367e17df]
tiledlayout(3, 1); %[output:367e17df]
ax1 = nexttile; %[output:367e17df]
plot(xl80Data.veloTime, xl80Data.velo, 'DisplayName', 'Raw'); %[output:367e17df]
hold on; %[output:367e17df]
plot(xl80Data.veloTime, xl80Data.velo_filtered, 'DisplayName', 'Filtered'); %[output:367e17df]
legend; %[output:367e17df]
title('Velocity curve before & after filtering'); %[output:367e17df]
ylabel('Velocity (m/s^2)'); %[output:367e17df]
set(gca, "XTickLabel", []); %[output:367e17df]

ax2 = nexttile; %[output:367e17df]
plot(xl80Data.accelTime, diff(xl80Data.velo) ./ diff(xl80Data.veloTime) ./ 60000, ... %[output:367e17df]
    "Color", [0, 0.4450, 0.7410]); %[output:367e17df]
title('Acceleration curve before filtering'); %[output:367e17df]
ylabel('Acceleration (m/s^2)'); %[output:367e17df]
set(gca, "XTickLabel", []); %[output:367e17df]

ax3 = nexttile; %[output:367e17df]
plot(xl80Data.accelTime, diff(xl80Data.velo) ./ diff(xl80Data.veloTime) ./ 60000, ... %[output:367e17df]
    'DisplayName', 'Original', "Color", [0, 0.4450, 0.7410] * 0.5 + [1, 1, 1] * 0.5); %[output:367e17df]
hold on; %[output:367e17df]
plot(xl80Data.accelTime, xl80Data.accel, 'DisplayName', 'Filtered'); %[output:367e17df]
ylim(1.1 * [min(xl80Data.accel), max(xl80Data.accel)]) %[output:367e17df]
title('Acceleration curve after filtering'); %[output:367e17df]
xlabel('Time (s)'); %[output:367e17df]
ylabel('Acceleration (m/s^2)'); %[output:367e17df]
legend; %[output:367e17df]
linkaxes([ax1, ax2, ax3], 'x'); %[output:367e17df]
drawnow;
%%
% fc = 5;
% % 输入信号分解
% x_sig_est = lowpass(diff(xl80Data.Displacement), fc, 1/(xl80Data.Time(2) - xl80Data.Time(1)));
% x_noise_est = diff(xl80Data.Displacement) - x_sig_est;
% 
% % 输出信号分解
% y_sig_est = lowpass(xl80Data.velo_filtered, fc, sampleRate);
% y_noise_est = xl80Data.velo_filtered - y_sig_est;
% 
% snr_in_est  = 10*log10(sum(x_sig_est.^2) / sum(x_noise_est.^2));
% snr_out_est = 10*log10(sum(y_sig_est.^2) / sum(y_noise_est.^2));
% snr_gain_est = snr_out_est - snr_in_est;
% 
% figure; 
% plot(theo_accelTime,theo_accel);
% plot(theo_veloTime,theo_velo);
% hold on;
% plot(xl80Data.accelTime, xl80Data.accel);
% 画加速度原始图像
% fig5 = figure('name', '【IDS】加速度图像');
% hLine = plot(xl80Data.accelTime, xl80Data.accel, 'LineWidth', 1);
% hAxes = ancestor(hLine, 'Axes');
% hold on;
% % title(hAxes, 'Acceleration 1 vs 2');
% ylim([min(xl80Data.accel), max(xl80Data.accel)]);
% xlabel('Time (s)');
% ylabel('Acceleration (m/s^2)');
%%
%[text] ## --------------------------- 位移分段分析 ---------------------------
%[text] 使用findpeaks函数，排除噪声并寻找所有局部最值。计算局部最值离理想值的差值，作为偏差
shiftTime = ceil(0.1 * sampleRate); % the time interval around the peak/valley value
dispPeaks = peak_segmentation(xl80Data.Time, xl80Data.Displacement, [], ...
    "IsNormalization", false, "MinPeakProminence", DISP_MinPeakProminence);
% calculate the disprange
dispPeaks.dispRange(:, 1) = dispPeaks.ind - shiftTime;
dispPeaks.dispRange(:, 2) = dispPeaks.ind + shiftTime + 1;
% add a line in the end, which is more convenient to be copied into excel
tmp = table(NaN, NaN, NaN, NaN, NaN, NaN, NaN, [NaN, NaN], 'VariableNames', dispPeaks.Properties.VariableNames);
dispPeaks(end + 1, :) = tmp; 
if strcmp(fileName(2), 'C')
    % if Measured point C, then eliminate the final peak value of each segment
    dispPeaksforAccel = dispPeaks;
    peakLength = size(dispPeaks, 1);
    for ii = 12 .* (1:floor(peakLength / 12))
        dispPeaks(ii, :) = tmp;
    end
end

plot_peaks(xl80Data.Time, xl80Data.Displacement, dispPeaks(1:2:end - 1, :), dispPeaks(2:2:end, :), ... %[output:group:0fcba196] %[output:7b95aca7]
    "PlotName", "【IDS】位移峰值"); %[output:group:0fcba196] %[output:7b95aca7]
drawnow;
%%
%[text] ## --------------------------- 速度指标计算 ---------------------------
ADJACENT_PARAM = 0.2 * sampleRate; % A3J5要改成1 * sampleRate
% Extract velocity segments from the signal
[velocitySegment, desiredValue, tLim1End] = velocity_segmentation(xl80Data.velo_filtered, ADJACENT_PARAM, 'case', 'IDS');

% Draw each segments of the velocity signal
fig5 = figure('Name', '【IDS】速度指标计算'); %[output:6778135a]
figPos = get(fig5, "Position");
screenPos = get(0, 'ScreenSize');
set(fig5, "Position", [figPos(1), figPos(2) - figPos(4), figPos(3), figPos(4)]); %[output:6778135a]
t1 = tiledlayout(fig5, 3, 1, "TileSpacing", "tight", 'Padding', 'tight'); %[output:6778135a]
n1 = nexttile(t1, 1, [2, 1]); %[output:6778135a]
hLine = plot(xl80Data.veloTime, xl80Data.velo_filtered, 'LineWidth', 0.5, 'DisplayName', 'Velocity'); %[output:6778135a]
hold on; %[output:6778135a]
for ii = 1:length(desiredValue)
    % if ~isnan(desiredValue(ii))
        plotObj = plot(xl80Data.veloTime(velocitySegment(ii, 1):velocitySegment(ii, 2)), ... %[output:6778135a]
            xl80Data.velo_filtered(velocitySegment(ii, 1):velocitySegment(ii, 2)), ... %[output:6778135a]
            'LineWidth', 1.25, 'LineStyle', '--'); %[output:6778135a]
        plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
    % end
end
sca1 = scatter(xl80Data.veloTime(velocitySegment(:, 1)), xl80Data.velo_filtered(velocitySegment(:, 1)), ... %[output:6778135a]
    36, 'MarkerEdgeColor', [0.8500 0.3250 0.0980], 'MarkerFaceColor', [0.8500 0.3250 0.0980], ... %[output:6778135a]
    'DisplayName', 'Strat Location', 'Marker', 'o'); %[output:6778135a]
sca2 = scatter(xl80Data.veloTime(velocitySegment(:, 2)), xl80Data.velo_filtered(velocitySegment(:, 2)), ... %[output:6778135a]
    12, 'MarkerEdgeColor', [0.9290 0.6940 0.1250], 'MarkerFaceColor', [0.9290 0.6940 0.1250], ... %[output:6778135a]
    'DisplayName', 'End Location', 'Marker', 'o'); %[output:6778135a]
legend('Location', 'best'); %[output:6778135a]
% title(n1, 'Segmented Velocity');
hAxes = ancestor(hLine, 'Axes');
tLim = [0, xl80Data.veloTime(tLim1End) + 5];
plotObj = plot(tLim, [5000, 5000], 'LineStyle', '--', 'LineWidth', 0.25, 'Color', [0.4, 0.4, 0.4]); %[output:6778135a]
plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
plotObj = plot(tLim, [-5000, -5000], 'LineStyle', '--', 'LineWidth', 0.25, 'Color', [0.4, 0.4, 0.4]); %[output:6778135a]
plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
plotObj = plot(tLim, [30000, 30000], 'LineStyle', '--', 'LineWidth', 0.25, 'Color', [0.4, 0.4, 0.4]); %[output:6778135a]
plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
plotObj = plot(tLim, [-30000, -30000], 'LineStyle', '--', 'LineWidth', 0.25, 'Color', [0.4, 0.4, 0.4]); %[output:6778135a]
plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
hAxes.XLim = tLim; %[output:6778135a]
ylabel('Velocity (mm/min)'); %[output:6778135a]

% Initialize for the velocity parameter struct, then changed into table
veloParam = struct("peakValue", {}, "peakError", {}, "peakMoment", {}, ...
    "steadyStateValue", {}, "steadyStateError", {}, "steadyStateMoment", {}, ...
    "riseTime", {}, "noiseLevel", {}, "overshoot", {}, ...
    "oscillationFrequency", {}, "settlingTime", {}, ...
    "peakValue0", {}, "peakError0", {}, "peakMoment0", {});

% A different method is used for thee measurement point D
% if strcmp(fileName(2), 'D')
%     isFluctuation = true;
% else
%     isFluctuation = false;
% end

% Calculate the velocity parameters for each segments
for ii = 1:size(velocitySegment, 1)
    % diffVelocitySegment = velocitySegment1(ii + 1) - velocitySegment1(ii);
    % if diffVelocitySegment > 1
    %     desiredValue = 5000; 
    % end
    % determine the desired value
    veloParam(ii) = velo_param( ...
        xl80Data.veloTime(velocitySegment(ii, 1):velocitySegment(ii, 2)), ...
        xl80Data.velo_filtered(velocitySegment(ii, 1):velocitySegment(ii, 2)), desiredValue(ii), ...
        'MinPeakProminence', VELO_MinPeakProminence, "Fluctuation", isFluctuation);
    % plotting for debug
    % plotObj = scatter(xl80Data.veloTime(velocitySegment(ii, 1)) + veloParam(ii).peakMoment, ...
    %     veloParam(ii).peakValue);
    % plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
    % plotObj = scatter(xl80Data.veloTime(velocitySegment(ii, 2)) - veloParam(ii).peakMoment0, ...
    %     veloParam(ii).peakValue0);
    % plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
    % drawnow;
end

% Add the item "startMoment" for each elements, and all the time-variables should be shifted 
%   considering the effect of the small overshoot at the beginning of the velocity-shifting process
for ii = 2:size(velocitySegment, 1)
    veloParam(ii).startMoment = xl80Data.veloTime(velocitySegment(ii, 1)) - veloParam(ii - 1).peakMoment0;
    veloParam(ii).startValue = veloParam(ii - 1).peakValue0;
    veloParam(ii).steadyStateMoment = veloParam(ii).steadyStateMoment + veloParam(ii - 1).peakMoment0;
    veloParam(ii).peakMoment = veloParam(ii).peakMoment + veloParam(ii - 1).peakMoment0;
    veloParam(ii).riseTime = veloParam(ii).riseTime + veloParam(ii - 1).peakMoment0;
    veloParam(ii).settlingTime = veloParam(ii).settlingTime + veloParam(ii - 1).peakMoment0;
end

% the startmoment of the first segment should be calculated here, i.e., the peak location before the 1st segment
[~, ind] = findpeaks(abs(xl80Data.velo_filtered(1:velocitySegment(1, 1))), "NPeaks", 1, 'SortStr', 'descend');
veloParam(1).startMoment = xl80Data.veloTime(ind);
veloParam(1).startValue = xl80Data.velo_filtered(ind);
deltaMoment = xl80Data.veloTime(velocitySegment(1, 1) - ind);
veloParam(1).steadyStateMoment = veloParam(1).steadyStateMoment + deltaMoment;
veloParam(1).peakMoment = veloParam(1).peakMoment + deltaMoment;
veloParam(1).riseTime = veloParam(1).riseTime + deltaMoment;
veloParam(1).settlingTime = veloParam(1).settlingTime + deltaMoment;

drawnow;
pause(2);
delete(sca1); delete(sca2); %[output:6778135a]
scatter([veloParam.startMoment], [veloParam.startValue], 36, ... %[output:6778135a]
    'MarkerEdgeColor', [0.8500 0.3250 0.0980], 'MarkerFaceColor', [0.8500 0.3250 0.0980], ... %[output:6778135a]
    'DisplayName', 'Seperate Location', 'Marker', 'diamond', 'MarkerFaceAlpha', 0.3); %[output:6778135a]
% plotObj = line(meshgrid([veloParam.startMoment], 1:2), max(xl80Data.velo_filtered) * ndgrid([-1, 1], 1:38), ...
%     "Color", [0.8500 0.3250 0.0980], "LineStyle", "-.");
% plotObj.Annotation.LegendInformation.IconDisplayStyle = "off";
scatter([veloParam.startMoment] + [veloParam.peakMoment], [veloParam.peakValue], 36, ... %[output:6778135a]
    'MarkerEdgeColor', [0.9290 0.6940 0.1250], 'MarkerFaceColor', [0.9290 0.6940 0.1250], ... %[output:6778135a]
    'DisplayName', 'Peaks', 'Marker', 'o', 'MarkerFaceAlpha', 0.3); %[output:6778135a]
scatter([veloParam.startMoment] + [veloParam.steadyStateMoment], [veloParam.steadyStateValue], 36, ... %[output:6778135a]
    'MarkerEdgeColor', [0.4660 0.6740 0.1880] * 0.5, ... %[output:6778135a]
    'DisplayName', 'Steady State', 'Marker', '*'); %[output:6778135a]

% change the data structure from struct to table, which is easier to duplicate
veloParam = struct2table(veloParam);

% 画图展示速度评价参数
nexttile(t1, 3); %[output:6778135a]
yyaxis left; %[output:6778135a]
bar(xl80Data.veloTime(velocitySegment(:, 1)), veloParam.peakError, 1, "LineStyle", "none"); %[output:6778135a]
ylabel('Peak error (mm/min)'); %[output:6778135a]
xlabel('Time (s)'); %[output:6778135a]
yyaxis right; %[output:6778135a]
plot(xl80Data.veloTime(velocitySegment(:, 1)), 100*veloParam.overshoot, ... %[output:6778135a]
    "Marker", "diamond", "Color", [0.8500 0.3250 0.0980], ... %[output:6778135a]
    "MarkerEdgeColor", [0.8500 0.3250 0.0980], "MarkerFaceColor", [0.8500 0.3250 0.0980]); %[output:6778135a]
ylabel('Overshoot'); %[output:6778135a]
ytickformat('%.1g%%'); %[output:6778135a]
xlim(tLim); %[output:6778135a]
legend("Peak error", "Overshoot percent", "Location", "best"); %[output:6778135a]
% nexttile(t1, 10, [1, 1]);
% yyaxis left;
% plot(xl80Data.veloTime(velocitySegment(:, 1)), veloParam.riseTime, 'o-', ...
%     'MarkerSize', 3, "MarkerFaceColor", [0 0.4470 0.7410]);
% hold on;
% yyaxis right;
% plot(xl80Data.veloTime(velocitySegment(:, 1)), veloParam.settlingTime, 'square-', ...
%     'MarkerSize', 3, "MarkerFaceColor", [0.8500 0.3250 0.0980]);
% xlim(tLim);
% legend("Rising time", "Setting time", "Location", "best");
% nexttile(t1, 11, [1, 1]);
% plot(xl80Data.veloTime(velocitySegment(:, 1)), veloParam.noiseLevel, ...
%     "Marker", "o", "MarkerSize", 3);
% xlim(tLim);
% legend("Noise level", "Location", "best");
% nexttile(t1, 12, [1, 1]);
% plot(xl80Data.veloTime(velocitySegment(:, 1)), veloParam.oscillationFrequency, ...
%     "Marker", "o", "MarkerSize", 3);
% xlim(tLim);
% legend("Oscillation frequency", "Location", "best");
drawnow;
%%
%[text] ## ------------------------------ 加速度指标计算 ------------------------------
%[text] 由于加速度数据的鲁棒性远远不及位移和速度，故分段和指标计算后的数据，单独检查后再拷贝到excel文件中
[accelPeaks,accelValleys] = peak_segmentation(xl80Data.accelTime, xl80Data.accel, ... %[output:group:9b8207f9] %[output:61d7093b]
    theoAccel, "PlotName", "【IDS】加速度峰谷值", "MinPeakDistance", ACCEL_MinPeakProminence); %[output:group:9b8207f9] %[output:61d7093b]
drawnow;
%%
%[text] ## --------------------------------- 指标整理 ---------------------------------
%[text] 位移、速度指标按Excel记录表格整理
paramExcel = save_excel(dispPeaks, veloParam);

% 加速度指标另外计算
num = size(paramExcel, 1);
if strcmp(fileName(2), 'C') %[output:group:21427fcf]
    accelExcel = accel_param2excel_C(xl80Data.accelTime, xl80Data.accel, num, ...
        accelPeaks, accelValleys, dispPeaksforAccel, "PlotName", "【IDS】加速度数据提取动画");
else
    accelExcel = accel_param2excel(xl80Data.accelTime, xl80Data.accel, num, ... %[output:14664410]
        accelPeaks, accelValleys, dispPeaks, "PlotName", "【IDS】加速度数据提取动画"); %[output:14664410]
end %[output:group:21427fcf]

% 合并加速度表格和位移速度表格
paramExcel = [paramExcel, accelExcel];
%%
%[text] ## ----------------------------------- 收尾 -----------------------------------
[pathstr, name, ~] = fileparts(FILE_PATH);
filePath1 = fullfile(pathstr, name);
if ~isfolder(filePath1)
    mkdir(filePath1);
end
fig_save(filePath1);

% 图像平铺
fig_tiled; %[output:937e8b87] %[output:1380f4b7] %[output:6bf0e2d7] %[output:2a89019a] %[output:8260da3b] %[output:9449dcbf] %[output:97644956] %[output:07f2da09]
fig_modal; %[output:937e8b87] %[output:1380f4b7] %[output:6bf0e2d7] %[output:2a89019a] %[output:8260da3b] %[output:9449dcbf] %[output:97644956] %[output:07f2da09]

